def ArithGeo(arr):
    if len(arr) < 3:
        return -1
    if all(arr[i] - arr[i-1] == arr[1] - arr[0] for i in range(2, len(arr))):
        return "Arithmetic"
    if arr[0] != 0 and all(
        arr[i] * arr[0] == arr[i-1] * arr[1] for i in range(2, len(arr))
    ):
        return "Geometric"
    return -1

