    for (int i = 2; i < n; i++) if (arr[i] - arr[i-1] != d) { d = Integer.MIN_VALUE; break; }
    if (d != Integer.MIN_VALUE) return "Arithmetic";
    if (arr[0] != 0) {
      for (int i = 2; i < n; i++) if (arr[i] * arr[0] != arr[i-1] * arr[1]) return -1;
      return "Geometric";
    }
    return -1;
  }
