solution.java:
public class Solution {
  public static String dashInsert(String str) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
      if (i > 0 && i % 2 == 1 && Character.isDigit(str.charAt(i))
          && Character.isDigit(str.charAt(i-1))) sb.append('-');
      sb.append(str.charAt(i));
    }
    return sb.toString();
  }
}

solution.rust:
impl Solution {
    pub fn dash_insert(str: &str) -> String {
        // One dash per *pair* of digits, not one per boundary, so "13579"
        // becomes "1-35-79" rather than "1-3-5-7-9".
        let mut out = String::new();
        for (i, ch) in str.chars().enumerate() {
            if i > 0 && i % 2 == 1 && ch.is_ascii_digit() && str.as_bytes()[i - 1].is_ascii_digit() {
                out.push('-');
            }
            out.push(ch);
        }
        out
    }
}

