public class Solution {
  public static int longestIncreasingSequence(int[] a) {
    if (a.length == 0) return 0;
    int[] best = new int[a.length];
    Arrays.fill(best, 1);
    int longest = 1;
    for (int i = 1; i < a.length; i++) {
      for (int j = 0; j < i; j++) if (a[j] < a[i]) best[i] = Math.max(best[i], best[j] + 1);
      longest = Math.max(longest, best[i]);
    }
    return longest;
  }
}

solution.rust:
impl Solution {
    pub fn longest_increasing_sequence(arr: Vec<i64>) -> i64 {
        // tails[k] is the smallest possible tail of an increasing run of
        // length k+1, so the answer is just how far the array is.
        let mut tails: Vec<i64> = Vec::new();
        for value in arr {
            let at = tails.partition_point(|t| *t < value);
            if at == tails.len() {
                tails.push(value);
            } else {
                tails[at] = value;
            }
        }
        tails.len() as i64
    }
}

