public class Program {
  public static object ArithGeoII(int[] arr) {
    int n = arr.Length;
    if (n < 3) return -1;
    int d = arr[1] - arr[0];
    bool arith = true;
    for (int i = 2; i < n; i++) if (arr[i] - arr[i-1] != d) { arith = false; break; }
    if (arith) return "Arithmetic";
    double ratio = (double)arr[1] / arr[0];
    for (int i = 2; i < n; i++) if ((double)arr[i] / arr[i-1] != ratio) return -1;
    return "Geometric";
  }
}

