impl Solution {
    pub fn caesar_cipher(str: &str, num: i64) -> String {
        let shift = ((num % 26) + 26) % 26;
        str.chars()
            .map(|c| {
                let base = if c.is_ascii_uppercase() { b'A' } else { b'a' };
                if c.is_ascii_alphabetic() {
                    let offset = (c as u8 - base) as i64;
                    (base + ((offset + shift) % 26) as u8) as char
                } else {
                    c
                }
            })
            .collect()
    }
}

