def IsAnagram(a, b):
    if len(a) != len(b):
        return "false"
    counts = {}
    for ch in a:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in b:
        if ch not in counts:
            return "false"
        counts[ch] -= 1
    return "true"

