def Trap(h):
    if not h:
        return 0
    left, right = 0, len(h) - 1
    left_max = right_max = 0
    total = 0
    while left < right:
        if h[left] < h[right]:
            left_max = max(left_max, h[left])
            total += left_max - h[left]
            left += 1
        else:
            right_max = max(right_max, h[right])
            total += right_max - h[right]
            right -= 1
    return total

