        while (i >= 0 || j >= 0 || carry != 0)
        {
            int total = carry;
            if (i >= 0) total += a[i--] - '0';
            if (j >= 0) total += b[j--] - '0';
            digits.Append((char)('0' + total % 2));
            carry = total / 2;
        }
        char[] outp = digits.ToString().ToCharArray();
