        int Depth(int node)
        {
            if (node >= root.Length || !root[node].HasValue) return 0;
            int left = Depth(2 * node + 1);
            int right = Depth(2 * node + 2);
            best = Math.Max(best, left + right);
            return Math.Max(left, right) + 1;
        }
        Depth(0);
        return best;
    }
}

