  int start = 0, best = 0;
  for (int index = 0; index < (int)s.size(); ++index) {
    char ch = s[index];
    auto found = last_seen.find(ch);
    if (found != last_seen.end() && found->second >= start) start = found->second + 1;
    last_seen[ch] = index;
    if (index - start + 1 > best) best = index - start + 1;
  }
  return best;
}

