def CourseSchedule(courseCount, prerequisites):
    outgoing = [[] for _ in range(courseCount)]
    for course, needed in prerequisites:
        outgoing[needed].append(course)
    # 0 = not looked at, 1 = on the current path, 2 = finished.
    state = [0] * courseCount
    for start in range(courseCount):
        if state[start] != 0:
            continue
        path = [(start, 0)]
        state[start] = 1
        while path:
            course, edge = path[-1]
            if edge == len(outgoing[course]):
                state[course] = 2
                path.pop()
                continue
            path[-1] = (course, edge + 1)
            nxt = outgoing[course][edge]
            if state[nxt] == 1:
                return False
            if state[nxt] == 0:
                state[nxt] = 1
                path.append((nxt, 0))
    return True

