def SortColors(nums):
    out = list(nums)
    low, middle, high = 0, 0, len(out) - 1
    while middle <= high:
        if out[middle] == 0:
            out[low], out[middle] = out[middle], out[low]
            low += 1
            middle += 1
        elif out[middle] == 2:
            out[middle], out[high] = out[high], out[middle]
            high -= 1
            # The middle cursor stays put: whatever was swapped in from the back
            # has not been looked at yet.
        else:
            middle += 1
    return out

