        reach[0] = true;
        for (int end = 1; end <= n; end++)
        {
            for (int start = 0; start < end; start++)
            {
                if (reach[start] && dictionary.Contains(str.Substring(start, end - start)))
                {
                    reach[end] = true;
                    break;
                }
            }
        }
        return reach[n];
    }
}

