            steps += 1;
            let mut next: std::collections::HashSet<String> = std::collections::HashSet::new();
            for word in &frontier {
                let chars: Vec<char> = word.chars().collect();
                for index in 0..chars.len() {
                    for letter in &letters {
                        if *letter == chars[index] {
                            continue;
